  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  font-size: 15px;
}
.preview-banner a { color: var(--c-lavender); }

/* ---------- Hero / cover decor ---------- */

.cover {
  position: relative;
  overflow: hidden;
  background: var(--c-pink);
  color: var(--c-white);
  isolation: isolate;
}

.cover--blue { background: var(--c-blue); }
